window.SHELF={"id": "obgyn", "name": "OB/GYN", "title": "OB/GYN Shelf Video Desk", "byline": "Dr High Yield \u00b7 Divine Intervention \u00b7 Mehlman", "hint": "Search a topic: preeclampsia, PPH, ectopic, PCOS\u2026", "order": ["h1", "h2", "d"], "pdfs": [{"id": "mehlman", "short": "Mehlman HY OB/GYN", "title": "Mehlman Medical HY Obgyn/Repro", "file": "Mehlman%20HY%20Obgyn.pdf", "pages": 128, "desc": "Mehlman free high-yield OB/GYN document."}, {"id": "divine", "short": "Divine Ep 22", "title": "Divine Intervention Episode 22 PDF", "file": "Divine%20Intervention%20Ep22.pdf", "pages": 167, "desc": "The 45 questions and topic slides he reads through in the episode."}]};
window.VIDS=[{"key": "h1", "id": "G2Om0nsR5t8", "who": "Dr High Yield", "title": "High Yield OB/GYN Review, Part 1", "len": 2985, "approx": false, "label": "H1", "c": "h1", "short": "Dr High Yield 1", "rail": "Dr High Yield, Part 1", "sections": [{"t": 27, "title": "Postpartum hemorrhage: atony, retained placenta, laceration", "notes": ["Over **500 mL vaginal or 1 L cesarean**. Most common cause: **uterine atony** (boggy uterus above the umbilicus). First line: **uterine massage**, then oxytocin.", "Retained placenta: incomplete placenta, **uneven endometrial lining** on ultrasound. Treat with **D&C**.", "Laceration: forceps delivery, firm uterus, even lining. **Inspect and suture**."]}, {"t": 195, "title": "Labour stages and arrest disorders", "notes": ["Latent 0 to 6 cm, **active 6 to 10 cm**.", "Arrest of active phase: no change with **4 h adequate or 6 h inadequate** contractions. Adequate = every 2 to 3 min or **over 200 Montevideo units** in 10 min. Treat with **cesarean**.", "Arrest of descent: over 3 h pushing (nullipara), usually **cephalopelvic disproportion**: cesarean."]}, {"t": 292, "title": "Uterine rupture and cord prolapse", "notes": ["Sudden intense pain, **loss of fetal station** (0 to -3), fetal parts hard to palpate: **uterine rupture**, laparotomy.", "Cord prolapse: **cesarean**."]}, {"t": 358, "title": "Fetal tachycardia and tachysystole", "notes": ["Normal FHR **110 to 160**. Tachycardia: think **maternal fever** (pyelonephritis, chorioamnionitis, endometritis).", "Tachysystole: **over 5 contractions in 10 min**, causes fetal bradycardia. Tocolytic (terbutaline). Tocolytic adverse effect: pulmonary edema."]}, {"t": 438, "title": "Normal physiology of pregnancy", "notes": ["Higher cardiac output and GFR, **glycosuria is normal**.", "**Respiratory alkalosis**: higher tidal volume, PaCO2 low. PaCO2 over 40 is abnormal.", "Plasma volume rises more than RBC mass: **physiologic anemia**. Beta thalassemia trait: high HbA2."]}, {"t": 503, "title": "Shoulder dystocia and birth injuries", "notes": ["Anterior shoulder stuck behind the pubic symphysis. First: **McRoberts** (hip hyperflexion).", "Risks: prior dystocia, **macrosomia** (gestational diabetes).", "Erb palsy (waiter tip) and clavicle fracture: **reassure**, they resolve.", "Pregestational diabetes: **congenital anomalies and heart defects**. Gestational: macrosomia, dystocia."]}, {"t": 653, "title": "Fetal bradycardia mechanisms", "notes": ["Maternal hypotension (epidural) causes spiral artery constriction and **reflex fetal bradycardia**.", "Cord compression, tachysystole also cause it."]}, {"t": 753, "title": "Nonstress test and biophysical profile", "notes": ["Reactive NST: **2 accelerations of 15 bpm for 15 s in 20 min**. Indication: decreased fetal movement.", "Nonreactive: **biophysical profile** (breathing, fluid, tone, movement, NST, out of 10). **4 or less = deliver**."]}, {"t": 849, "title": "Endometritis and chorioamnionitis", "notes": ["Endometritis: after cesarean, fever, **tender uterus, foul lochia**. **Clindamycin + gentamicin**.", "Chorioamnionitis: prolonged rupture of membranes (**over 18 h**). **Ampicillin + gentamicin**."]}, {"t": 948, "title": "Prenatal screening: AFP and Down syndrome", "notes": ["Increased nuchal translucency: trisomy 21 or 18.", "AFP **over 2 to 2.5 MoM**: neural tube defect, abdominal wall defect. **Most common cause: wrong dates**.", "Down syndrome: nuchal fold, **duodenal atresia (double bubble)**."]}, {"t": 1035, "title": "Twins and clomiphene", "notes": ["Twins: higher preterm birth, anomalies, preeclampsia, PPH.", "Clomiphene: **estrogen receptor antagonist at the hypothalamus**, more GnRH, LH, FSH. Ovulation induction in **PCOS**, risk of multiples."]}, {"t": 1097, "title": "Rh disease and Kleihauer-Betke", "notes": ["Rh-negative mother sensitized by fetal blood (abruption, delivery), **IgG crosses** next pregnancy and causes hemolysis, hydrops.", "**Kleihauer-Betke** measures fetal blood in maternal circulation to dose anti-D (RhoGAM)."]}, {"t": 1292, "title": "Preeclampsia and eclampsia", "notes": ["BP **140/90 after 20 weeks + proteinuria** (protein:creatinine over 0.3 or 300 mg/day).", "Severe features: **160/110**, kidney injury, high liver enzymes, headache, visual change, pulmonary edema.", "Eclampsia = seizures. Pulmonary edema: furosemide."]}, {"t": 1401, "title": "Herpes in pregnancy", "notes": ["**Acyclovir from 36 weeks**. Vaginal delivery if no lesions or prodrome.", "Active lesions or prodrome: **cesarean**."]}, {"t": 1439, "title": "Genital ulcers: chancroid vs syphilis", "notes": ["Chancroid (H ducreyi): **painful**, ragged necrotic base, school of fish. Ceftriaxone or azithromycin.", "Syphilis chancre: **painless**, clean hard border. **IM penicillin G**. Secondary: condyloma lata, palms and soles. Neurosyphilis: IV penicillin."]}, {"t": 1504, "title": "Third-trimester bleeding: abruption, previa, accreta", "notes": ["Abruption: **painful** bleeding, contractions. Risks: trauma, hypertension, **cocaine, smoking**, prior abruption.", "Previa: **painless** bleeding, placenta over the os. Risk: prior cesarean. **No digital exam**.", "Accreta, increta, percreta (bladder, hematuria): **planned cesarean hysterectomy**."]}, {"t": 1649, "title": "Skin and liver disorders of pregnancy", "notes": ["Intrahepatic cholestasis: **itchy palms and soles at night, high bile acids**. **Ursodiol**, deliver at 37 weeks.", "PUPPP: itchy papules in **striae**, spares umbilicus, benign. Topical steroids.", "Pemphigoid gestationis: **vesicles around the umbilicus**. Steroids.", "Acute fatty liver: vomiting, **hypoglycemia**, high LFTs, coagulopathy. **Deliver now**."]}, {"t": 1783, "title": "DVT, PE and amniotic fluid embolism", "notes": ["Pregnancy is hypercoagulable. DVT: **compression ultrasound**. PE: V/Q or CT (both low dose). **LMWH** in pregnancy, not DOACs.", "Amniotic fluid embolism: sudden hypoxia, hypotension, **DIC** during labour. Supportive."]}, {"t": 1871, "title": "Magnesium for preeclampsia", "notes": ["Severe features or eclampsia: **magnesium sulfate + deliver**.", "First sign of toxicity: **loss of deep tendon reflexes**. Antidote: calcium gluconate."]}, {"t": 1916, "title": "Preterm labour drugs by gestational age", "notes": ["**Magnesium under 32 weeks** for neuroprotection (cerebral palsy).", "Tocolytics (nifedipine, indomethacin) **up to 34 weeks**.", "**Betamethasone 24 to 34 weeks** for lung maturity (some up to 36+6)."]}, {"t": 2002, "title": "Neonatal infections and PPROM", "notes": ["Under 3 months: **GBS, E coli, Listeria**.", "PPROM causes **oligohydramnios**, cord compression, **variable decelerations**."]}, {"t": 2059, "title": "Fetal heart rate decelerations", "notes": ["Early: head compression, mirror image, benign.", "Late: **uteroplacental insufficiency**, after the contraction peak.", "Variable: **cord compression**, abrupt. Reposition, **amnioinfusion**."]}, {"t": 2114, "title": "Parvovirus B19 and hydrops", "notes": ["Mother: arthralgias, rash. Fetus: destroys RBC precursors, **anemia, high-output heart failure, hydrops**.", "FHR: **sinusoidal pattern**. **MCA Doppler** detects fetal anemia.", "Maternal lupus (anti-Ro): **congenital heart block**."]}, {"t": 2266, "title": "TORCH infections", "notes": ["CMV: chorioretinitis, microcephaly, **periventricular calcifications**.", "Toxoplasma: **diffuse calcifications**, hydrocephalus. Spiramycin, then pyrimethamine + sulfadiazine.", "Rubella: cataracts, deafness, **PDA**."]}, {"t": 2326, "title": "Amniotic fluid, IUGR and Dopplers", "notes": ["AFI normal 5 to 25. **Under 5 oligo, over 25 poly**.", "IUGR: under 10th percentile. **Umbilical artery Doppler**: reversed flow = deliver."]}, {"t": 2386, "title": "Neonatal conjunctivitis, HIV, hepatitis B", "notes": ["Gonococcal **day 2 to 5**: topical erythromycin prophylaxis, ceftriaxone treatment. Chlamydia **day 5 to 14**: **oral** erythromycin.", "HIV: vaginal delivery if viral load low (Canada: **under 50**). Higher: cesarean + IV zidovudine.", "Hep B mother: **HBIG + vaccine at birth**."]}, {"t": 2443, "title": "Postpartum thyroiditis", "notes": ["Anti-TPO. Painless **hyperthyroid with low iodine uptake**, then hypothyroid, then recovers.", "Graves: diffuse high uptake."]}, {"t": 2558, "title": "Symmetric vs asymmetric growth restriction", "notes": ["Symmetric: early insult, **chromosomal, TORCH**.", "Asymmetric (head sparing): **placental insufficiency**, hypertension, smoking."]}, {"t": 2613, "title": "UTI and asymptomatic bacteriuria", "notes": ["Screen urine culture in first trimester. **Treat asymptomatic bacteriuria** (pyelonephritis risk).", "Safe: **amoxicillin, cephalexin, nitrofurantoin** (avoid near term). Avoid TMP-SMX first trimester and fluoroquinolones."]}, {"t": 2671, "title": "GBS prophylaxis", "notes": ["Swab at **35 to 37 weeks** (Canada 35 to 37). **IV penicillin G** at least 4 h before delivery.", "Always treat: prior GBS-infected baby, **GBS bacteriuria** this pregnancy.", "Unknown status: **preterm, ROM over 18 h, fever**."]}, {"t": 2773, "title": "Postpartum infections and breastfeeding", "notes": ["Post-cesarean fever: **endomyometritis**: clindamycin + gentamicin.", "Breast abscess (**fluctuant**, S aureus): **drainage + dicloxacillin or cephalexin**. Mastitis: keep breastfeeding.", "Breast milk lacks **vitamin D and K**. Exclusive breastfeeding to 6 months."]}, {"t": 2863, "title": "Prenatal visits and gestational diabetes", "notes": ["First visit: CBC, blood group, rubella, HIV, syphilis, hep B, urine culture.", "24 to 28 weeks: **50 g screen** (Canada: over 7.8 positive, over 11.1 diagnostic). Then **75 g OGTT** (Canada) or 100 g.", "Treat: diet first, then **insulin**.", "Fundal height off by over 2 cm: **ultrasound**."]}]}, {"key": "h2", "id": "bledEHU6q3M", "who": "Dr High Yield", "title": "High Yield OB/GYN Review, Part 2", "len": 2956, "approx": false, "label": "H2", "c": "h2", "short": "Dr High Yield 2", "rail": "Dr High Yield, Part 2", "sections": [{"t": 2, "title": "Screening and vaccines", "notes": ["US ages in the video. Canada: **mammography 50 to 74 every 2 years** (discuss from 40), DEXA at 65, HPV vaccine 9 to 26.", "Pap: **from 21, every 3 years**, stop around 65 (Manitoba moving to HPV testing). HIV: yearly."]}, {"t": 43, "title": "Galactorrhea, amenorrhea and bone loss", "notes": ["Prolactinoma, **hypothyroidism** (TRH raises prolactin), pregnancy all cause galactorrhea.", "High prolactin suppresses GnRH, **low estrogen, osteoporosis**.", "Female athlete triad: low energy, **hypothalamic amenorrhea**, low bone density, **stress fractures**."]}, {"t": 182, "title": "Secondary amenorrhea first steps and emergency contraception", "notes": ["First: **beta hCG**, then TSH and prolactin.", "Most effective emergency contraception: **copper IUD** (within 5 to 7 days). Avoid with heavy bleeding."]}, {"t": 225, "title": "Postoperative fever: the 5 Ws", "notes": ["Wind (atelectasis, pneumonia) day 1 to 2, Water (**UTI**) day 3, Walking (**DVT**) day 5, Wound day 7, Wonder drugs or abscess day 7+."]}, {"t": 266, "title": "Urinary incontinence", "notes": ["Stress: leak with cough, **urethral hypermobility** (Q-tip test). **Pelvic floor (Kegel)**, pessary, then midurethral sling.", "Urge: overactive detrusor. **Bladder training**, then antimuscarinic (oxybutynin) or mirabegron.", "Overflow: diabetic neuropathy, post-op. **Post-void residual over 100 mL**. Intermittent catheterization."]}, {"t": 432, "title": "Pelvic organ prolapse and pelvic causes of constipation", "notes": ["Cystocele (anterior wall), **rectocele** (posterior, splinting to defecate), enterocele, **uterine prolapse** (smooth mass at the introitus).", "Fibroids compress the rectum. Endometriosis: **dyschezia**."]}, {"t": 526, "title": "Post-cesarean wound complications", "notes": ["Evisceration: **cover with saline-soaked sponge, OR**.", "Fascial dehiscence: **salmon-coloured fluid**, binder and OR.", "Wound infection: red, tender, fever. **Open, drain, antibiotics**."]}, {"t": 593, "title": "Pelvic inflammatory disease", "notes": ["Chlamydia and gonorrhea ascend: cervicitis, salpingitis, **tubo-ovarian abscess**, Fitz-Hugh-Curtis (RUQ perihepatitis).", "Signs: **cervical motion tenderness**, uterine and adnexal tenderness, fever.", "TOA: **clindamycin + gentamicin** or cefoxitin + doxycycline, drain if large."]}, {"t": 659, "title": "Vaginitis: trich, BV, candida", "notes": ["Trichomonas: **green frothy discharge, strawberry cervix**, motile organisms. Metronidazole, **treat partner**.", "BV (Gardnerella): thin grey fishy discharge, **clue cells, positive whiff**, pH over 4.5. Metronidazole. Not sexually transmitted.", "Candida: **thick curd-like discharge**, itch, normal pH, diabetes. Azoles."]}, {"t": 757, "title": "Adenomyosis, dysmenorrhea, endometriosis", "notes": ["Adenomyosis: **uniformly enlarged boggy tender uterus**, heavy painful periods. NSAIDs, hormones, hysterectomy.", "Primary dysmenorrhea: prostaglandins. **NSAIDs**.", "Endometriosis: **dysmenorrhea, dyspareunia, dyschezia**, nodular uterosacral ligaments, infertility. NSAIDs, OCPs, **laparoscopy** to diagnose."]}, {"t": 845, "title": "LGV and granuloma inguinale", "notes": ["LGV (Chlamydia L1 to L3): painless ulcer, then **painful buboes**. Doxycycline.", "Granuloma inguinale (Klebsiella): **beefy red painless ulcers**, no buboes. Azithromycin."]}, {"t": 903, "title": "Interstitial cystitis and hematuria", "notes": ["Sterile urine, pain **relieved by voiding**: interstitial cystitis.", "Painful gross hematuria: stones, infection. **Painless gross hematuria + smoker: bladder or kidney cancer**."]}, {"t": 975, "title": "Fibroids and leiomyosarcoma", "notes": ["Irregular non-tender enlarged uterus, **heavy bleeding**, anemia. NSAIDs, progestin or IUD, GnRH agonist, myomectomy or hysterectomy.", "**Rapid growth after menopause or prior pelvic radiation**: leiomyosarcoma."]}, {"t": 1016, "title": "Types of miscarriage", "notes": ["Threatened: bleeding, **closed os**, viable.", "Inevitable: **open os**, products in the uterus.", "Incomplete: some tissue passed, open os. Complete: all passed, closed os.", "Missed: no bleeding, **nonviable fetus**."]}, {"t": 1078, "title": "Ectopic pregnancy", "notes": ["hCG over the discriminatory zone (**1500 to 3500**) and **empty uterus**: ectopic.", "Stable, small, no heartbeat, hCG under 5000: **methotrexate**.", "Unstable or rupture: **laparoscopic salpingectomy** (salpingostomy if other tube damaged)."]}, {"t": 1166, "title": "Molar pregnancy and choriocarcinoma", "notes": ["Very high hCG, **large uterus, snowstorm**, early preeclampsia, hyperemesis, theca lutein cysts.", "Complete: **46,XX** (empty egg). Partial: **69,XXY**, fetal parts.", "**Suction D&C**, then **serial hCG to zero** with reliable contraception. Rising hCG: choriocarcinoma (lung mets)."]}, {"t": 1264, "title": "Septic abortion and Listeria", "notes": ["Retained products, **fever, foul discharge**. **Broad IV antibiotics + D&C**.", "Listeria: chorioamnionitis with **intact membranes** (hematogenous). Ampicillin.", "Chorioamnionitis: antibiotics and **deliver**."]}, {"t": 1384, "title": "Breast masses", "notes": ["Fibroadenoma: young, **firm rubbery mobile**. Fibrocystic: tender, varies with cycle.", "Under 30: **ultrasound**. 30 and over: **mammogram + ultrasound**. Suspicious: core biopsy.", "Bloody nipple discharge: **intraductal papilloma**.", "Cyst: aspirate. Clear and resolves: reassure. **Bloody or persists: cytology and biopsy**."]}, {"t": 1493, "title": "Inflammatory breast cancer, Paget, BRCA", "notes": ["**Peau d orange**, red warm breast, no response to antibiotics: inflammatory carcinoma, biopsy.", "Nipple eczema that does not heal: **Paget disease**, underlying carcinoma.", "BRCA: early breast and **ovarian cancer**, male breast cancer, Ashkenazi. **MRI from 25**, consider risk-reducing surgery.", "Triple negative: worst prognosis."]}, {"t": 1601, "title": "Asherman syndrome and secondary amenorrhea workup", "notes": ["Amenorrhea after **D&C**: intrauterine adhesions. Diagnose by **hysteroscopy** (or saline sonogram), lyse adhesions.", "Workup: hCG, TSH, prolactin, then **progestin challenge**. Bleeds = anovulation (PCOS). No bleed: check FSH.", "High FSH: **ovarian insufficiency** (under 40). Low FSH: hypothalamic. Normal with no bleed: outflow (Asherman).", "Prolactinoma: **cabergoline**."]}, {"t": 1762, "title": "PCOS, Sheehan, androgen-secreting tumours", "notes": ["PCOS: obesity, **hirsutism, irregular periods since teens**, many follicles. **Weight loss**, then OCPs. Fertility: **letrozole** (or clomiphene). Screen for diabetes and lipids.", "Sheehan: **PPH then no lactation**, panhypopituitarism.", "Sertoli-Leydig: **rapid virilization** (deep voice, clitoromegaly) + ovarian mass.", "Granulosa cell: estrogen, **precocious puberty** or postmenopausal bleeding. Teratoma: most common in young."]}, {"t": 1931, "title": "Ovarian torsion", "notes": ["Sudden severe unilateral pain, nausea, **adnexal mass**.", "**Ultrasound with Doppler**, then **laparoscopic detorsion** (keep the ovary)."]}, {"t": 1981, "title": "Congenital adrenal hyperplasia", "notes": ["21-hydroxylase: **salt wasting** (low Na, high K, hypotension), virilization. **High 17-hydroxyprogesterone**.", "11-hydroxylase: virilization + **hypertension** (11-deoxycorticosterone).", "17-hydroxylase: **hypertension, no sex hormones**."]}, {"t": 2114, "title": "Turner syndrome", "notes": ["45,X. Webbed neck, shield chest, **bicuspid aortic valve, coarctation**, horseshoe kidney, **streak ovaries**.", "High FSH and LH. **Estrogen** for puberty, growth hormone. Y material: **remove gonads**."]}, {"t": 2182, "title": "Mullerian agenesis vs androgen insensitivity", "notes": ["Both: primary amenorrhea, **no uterus**, breasts present.", "Mullerian agenesis: **46,XX**, normal pubic hair, normal female testosterone.", "Androgen insensitivity: **46,XY**, **no pubic or axillary hair**, high testosterone, testes. **Remove testes after puberty**."]}, {"t": 2356, "title": "Kallmann syndrome and infertility", "notes": ["Kallmann: **anosmia** + low GnRH, LH, FSH, delayed puberty.", "Infertility: **1 year** of trying (6 months if 35+). Start with **semen analysis** and ovulation check."]}, {"t": 2414, "title": "Endometrial cancer", "notes": ["**Postmenopausal bleeding**: transvaginal ultrasound. Stripe **over 4 mm**: endometrial biopsy (biopsy anyway if bleeding persists).", "Under 45 with risk (obesity, PCOS, unopposed estrogen): **biopsy**.", "Treatment: **hysterectomy** + staging."]}, {"t": 2496, "title": "Abnormal Pap and cervical cancer", "notes": ["AGC: **colposcopy + endometrial sampling**.", "LSIL or HSIL: **colposcopy**. ASCUS: **HPV reflex**, positive goes to colposcopy.", "**Postcoital bleeding**: cervical cancer until proven otherwise. HPV 16 and 18 cause cancer, 6 and 11 warts."]}, {"t": 2582, "title": "Ovarian, vulvar cancer and lichen sclerosus", "notes": ["Ovarian mass + **ascites, weight loss**: ultrasound (septations, solid parts), CA-125. **No percutaneous biopsy** (seeding), go to surgery.", "Vulvar itch or mass in older woman: **biopsy** (squamous cell).", "Lichen sclerosus: **thin white cigarette-paper skin**, clitoral phimosis. Biopsy, **clobetasol**.", "Atrophic vaginitis: dry, postmenopausal. **Vaginal estrogen**."]}, {"t": 2679, "title": "Theca lutein cysts, toxic shock, fetal demise", "notes": ["Virilization during pregnancy: **luteoma or theca lutein cyst**, resolves.", "Toxic shock: **tampon** or nasal packing, hypotension, diffuse rash with **palm and sole desquamation**. Remove source, fluids, antibiotics.", "No fetal heart on Doppler: **ultrasound** to confirm."]}, {"t": 2734, "title": "Magnesium toxicity and Down syndrome screening", "notes": ["Magnesium toxicity: **loss of reflexes first**. **Calcium gluconate**.", "Oligohydramnios: **pulmonary hypoplasia**.", "First trimester: nuchal translucency, hCG, **PAPP-A**. Quad: AFP low, hCG high, estriol low, **inhibin high**.", "Confirm: **CVS 10 to 13 weeks**, amniocentesis **15+ weeks**. Cell-free DNA is now first line screen."]}, {"t": 2794, "title": "Child and elder abuse", "notes": ["Spiral fractures, bruises of different ages, **stocking burns sparing creases**, injury beyond milestones, **retinal hemorrhages**.", "First: **admit to separate and protect**, then report to child protection (mandatory).", "Elder abuse: usually the **caregiver**."]}, {"t": 2866, "title": "Antibiotic and drug review", "notes": ["Endometritis: clindamycin + gentamicin. Chorioamnionitis: **ampicillin + gentamicin**. TOA: clindamycin + gentamicin or cefoxitin + doxycycline.", "Pregnancy UTI: **cephalexin, amoxicillin, nitrofurantoin**.", "Chlamydia: **azithromycin** (pregnancy) or doxycycline. Gonorrhea: **ceftriaxone** + chlamydia cover."]}]}, {"key": "d", "id": "EEwhWOXHyHA", "who": "Divine Intervention", "title": "Episode 22: Comprehensive OB/GYN Shelf Review", "len": 8097, "approx": true, "label": "D", "c": "d", "short": "Divine Ep 22", "rail": "Divine Intervention Ep 22", "sections": [{"t": 60, "title": "How to approach the OB/GYN shelf", "notes": ["Management-heavy shelf. Learn **risk factors, sequential management steps** and disease scripts.", "UWorld + NBME forms. Pick the simple answer with the most evidence."], "p": 2}, {"t": 156, "title": "Postpartum contraception and breastfeeding", "notes": ["Postpartum and breastfeeding: **progestin-only** (DMPA, pill, implant, IUD). Avoid estrogen (cuts milk supply).", "DMPA: delayed return of fertility (up to a year), bone loss, weight gain.", "Breastfeeding lowers **breast and ovarian cancer**. Contraindications: HIV (in Canada), active TB, **herpes on the breast**, galactosemia. Mastitis: keep breastfeeding, dicloxacillin."], "p": 4}, {"t": 300, "title": "Postpartum blues, depression, psychosis", "notes": ["Blues: tearful, **within 2 weeks**, functioning. **Reassure**.", "Depression: 2+ weeks, 5 of 9 SIGECAPS, thoughts of harming baby with remorse. **SSRI** (sertraline).", "Psychosis: hallucinations, delusions about the baby. **Admit, antipsychotic**."], "p": 7}, {"t": 397, "title": "Endometritis vs chorioamnionitis", "notes": ["Endometritis: biggest risk factor **cesarean delivery**. Fever, tender uterus, foul lochia. **Clindamycin + gentamicin**.", "Chorioamnionitis: **prolonged ROM**, maternal fever, fetal tachycardia over 160. Ampicillin + gentamicin, deliver."], "p": 9}, {"t": 541, "title": "Normal physiology of pregnancy", "notes": ["Chadwick sign, chloasma. **BP falls** in the first half (progesterone).", "Plasma volume **+50%**, RBC mass +30%: dilutional anemia. **Cardiac output up**, falls supine (IVC compression).", "Respiratory alkalosis, higher GFR, hypercoagulable."], "p": 12}, {"t": 734, "title": "Fetal demise", "notes": ["Confirm with **ultrasound**. Console, respect wishes, **induce for vaginal delivery** (or expectant).", "Prolonged retained demise: risk of **DIC**."], "p": 16}, {"t": 830, "title": "First-visit urinalysis and pyelonephritis", "notes": ["Screen for **asymptomatic bacteriuria** at the first visit, treat it (pyelonephritis risk).", "Pyelonephritis in pregnancy: **admit, IV ceftriaxone**."], "p": 18}, {"t": 926, "title": "Prenatal test timing", "notes": ["CVS **10 to 13 weeks**. Cell-free DNA from 10 weeks. Amniocentesis and quad screen **15 to 20 weeks**. Anatomy scan 18 to 20.", "GDM screen **24 to 28**. Anti-D **28 weeks** and within 72 h postpartum. GBS swab **35 to 37**.", "High AFP: NTD, abdominal wall defects, twins, **wrong dates (most common)**."], "p": 20}, {"t": 1119, "title": "Weight gain in pregnancy", "notes": ["Underweight (BMI under 18.5): **28 to 40 lb**. Normal: **25 to 35**. Overweight: **15 to 25**. Obese: **11 to 20**."], "p": 24}, {"t": 1264, "title": "Menopause, vaginitis and menopause treatment", "notes": ["Menopause: **high FSH and LH**, low estrogen. Hot flashes: **hormone therapy** (with progestin if uterus present).", "Candida: hyphae on KOH, pH under 4.5, diabetes, antibiotics.", "Dyspareunia: lubricants, **vaginal estrogen**."], "p": 27}, {"t": 1456, "title": "Hyperemesis gravidarum", "notes": ["Over 5% weight loss + ketosis. **Hypokalemic hypochloremic metabolic alkalosis**.", "Associated with **molar pregnancy and twins**. Fluids, antiemetics (doxylamine-pyridoxine, ondansetron), thiamine before glucose."], "p": 31}, {"t": 1553, "title": "Hypertension in pregnancy", "notes": ["Chronic: before pregnancy or before 20 weeks. **Stop ACE inhibitors and ARBs**. Switch to **labetalol, nifedipine, methyldopa**.", "Gestational: over 140/90 after 20 weeks, no proteinuria.", "Preeclampsia: + proteinuria or organ involvement. Severe features: **160/110**, low platelets, high LFTs or creatinine, headache, visual change. Magnesium + deliver. HELLP."], "p": 33}, {"t": 1745, "title": "Teratogens", "notes": ["Lithium: **Ebstein anomaly**. Tetracycline: teeth. Fluoroquinolones: cartilage.", "**Warfarin**: stippled epiphyses, use heparin. DES: clear cell vaginal cancer, T-shaped uterus.", "ACE inhibitors and ARBs: fetal kidneys. Valproate: NTD. Isotretinoin: needs **2 forms of contraception**."], "p": 37}, {"t": 1938, "title": "Amniotic fluid embolism", "notes": ["Collapse during or right after delivery: **hypotension, hypoxia, then DIC** (oozing).", "Supportive. Distinguish from PE (no DIC) and epidural toxicity."], "p": 41}, {"t": 2034, "title": "Breast triggers and benign breast disease", "notes": ["Gynecomastia on spironolactone. **Mastitis**: keep feeding, dicloxacillin. Abscess: drain.", "Fibrocystic: multiple tender masses that vary with the cycle. Fibroadenoma: solitary mobile.", "Bloody discharge: **intraductal papilloma**. Leaf-like: **phyllodes**. BRCA2: male breast cancer."], "p": 43}, {"t": 2131, "title": "Breast mass algorithm", "notes": ["Over 30 with a mass: **diagnostic mammogram + ultrasound**. A palpable mass with a negative mammogram still gets **core biopsy**.", "Under 30: **ultrasound**. Solid: **core biopsy**. Cyst: aspirate. Bloody fluid or recurs: core biopsy.", "Young with cyclic multiple tender masses: reassure, recheck after menses.", "BRCA: **MRI + mammogram**, risk-reducing mastectomy and salpingo-oophorectomy."], "p": 45}, {"t": 2516, "title": "Uterine rupture", "notes": ["**Prior classical incision**, sudden severe pain, loss of station, fetal distress. **Emergency laparotomy**.", "Classical incision: **repeat cesarean**, no trial of labour."], "p": 53}, {"t": 2612, "title": "Postpartum hemorrhage: the 4 Ts", "notes": ["Over **500 mL vaginal, 1000 mL cesarean**.", "**Tone** (atony, most common): massage, oxytocin, then carboprost (**not in asthma**), methylergonovine (**not in hypertension**), misoprostol, tranexamic acid.", "**Trauma** (lacerations), **Tissue** (retained, accreta), **Thrombin** (DIC).", "Uterine inversion: **replace the uterus** before removing placenta.", "Refractory: balloon tamponade, arterial ligation or embolization, hysterectomy. Sheehan syndrome after."], "p": 55}, {"t": 3142, "title": "Abnormal uterine bleeding: PALM-COEIN", "notes": ["Structural: **Polyp, Adenomyosis, Leiomyoma, Malignancy**. Nonstructural: **Coagulopathy (von Willebrand), Ovulatory, Endometrial, Iatrogenic, Not classified**.", "Fibroids: **asymmetric nodular** uterus. Adenomyosis: **symmetric boggy**.", "Treatment: hormonal IUD, OCPs, progestin, **tranexamic acid**. Life-threatening: IV fluids, transfuse, **IV estrogen**, D&C."], "p": 66}, {"t": 3479, "title": "Polycystic ovary syndrome", "notes": ["**2 of 3**: oligo-anovulation, hyperandrogenism, polycystic ovaries. Rule out TSH, prolactin, CAH (17-OHP), androgen tumour (DHEAS, testosterone).", "Risks: diabetes, metabolic syndrome, **endometrial hyperplasia and cancer**, infertility.", "Treat: **weight loss**, OCPs, spironolactone for hirsutism, metformin. Ovulation: **letrozole** or clomiphene."], "p": 73}, {"t": 4009, "title": "Shoulder dystocia and Erb palsy", "notes": ["Turtle sign. **McRoberts + suprapubic pressure**, then rotational manoeuvres, posterior arm.", "Excess traction: **Erb-Duchenne palsy (C5 to C6)**, waiter tip."], "p": 84}, {"t": 4202, "title": "Fetal heart rate tracings", "notes": ["Early: **head compression**, mirror image, benign.", "Variable: **cord compression**, abrupt. Reposition, amnioinfusion.", "Late: **uteroplacental insufficiency**. Reposition, oxygen, fluids, stop oxytocin, deliver if persistent.", "Sinusoidal: **severe fetal anemia**. Check fetal hematocrit (PUBS)."], "p": 88}, {"t": 4587, "title": "Molar pregnancy and choriocarcinoma", "notes": ["Partial: **69,XXY**, fetal parts. Complete: **46,XX**, no fetal parts, higher cancer risk.", "Very high hCG, snowstorm. **Suction curettage**, then serial hCG with contraception.", "Bleeding + shortness of breath after a mole, high hCG: **choriocarcinoma**, chest x-ray, **methotrexate**."], "p": 96}, {"t": 4876, "title": "Rh alloimmunization", "notes": ["Rh-negative, antibody negative: **anti-D at 28 weeks** and within 72 h postpartum, plus after bleeding or procedures.", "Already sensitized: **check father**. If positive, follow **MCA Doppler**, intrauterine transfusion for anemia.", "Kleihauer-Betke sets the postpartum dose."], "p": 102}, {"t": 4972, "title": "Placenta previa, accreta, vasa previa", "notes": ["Painless bleeding with prior cesareans: **previa**. **Ultrasound, no digital exam**.", "Accreta (adheres), increta (into myometrium), percreta (bladder). Linked to **prior cesareans**.", "Bleeding at ROM + fetal bradycardia or late decelerations: **vasa previa**, emergency cesarean."], "p": 104}, {"t": 5165, "title": "Abruption, PROM and preterm labour", "notes": ["Painful bleeding, trauma, **cocaine, hypertension**: abruption. Urgent delivery if unstable.", "ROM confirmed by **ferning and nitrazine**. Term PROM: induce. PPROM: antibiotics (ampicillin + erythromycin), steroids, deliver at 34+ weeks.", "Preterm labour: steroids (to 34), magnesium (under 32), tocolysis. **Fetal fibronectin**: negative is reassuring."], "p": 108}, {"t": 5358, "title": "Oligohydramnios and polyhydramnios", "notes": ["Oligo: **renal agenesis (Potter)**, posterior urethral valves, PROM. Pulmonary hypoplasia.", "Poly: **anencephaly, esophageal or duodenal atresia**, maternal diabetes."], "p": 112}, {"t": 5454, "title": "Twins and twin-twin transfusion", "notes": ["Monochorionic twins: **twin-twin transfusion**. Donor anemic and small, recipient polycythemic, overloaded.", "Split timing: days 0 to 4 di-di, 4 to 8 mono-di, 8 to 12 mono-mono, after 13 **conjoined**."], "p": 114}, {"t": 5550, "title": "Ectopic pregnancy", "notes": ["Pain + bleeding + positive hCG. Risks: **prior ectopic, PID, tubal surgery, smoking, IUD failure**.", "Unstable: surgery. Stable, hCG under 5000, no heartbeat, normal kidneys and liver: **methotrexate**."], "p": 116}, {"t": 5695, "title": "Types of miscarriage", "notes": ["Threatened: closed os, viable. Inevitable: **open os**. Incomplete: tissue passed, open os. Complete: closed os, empty. Missed: nonviable, no symptoms.", "Manage with expectant, **misoprostol** or D&C. Septic: antibiotics + D&C."], "p": 119}, {"t": 5887, "title": "TORCH and congenital infections", "notes": ["Toxoplasma: **diffuse calcifications**, hydrocephalus, cats.", "Parvovirus: hydrops. VZV: limb hypoplasia, skin scars. **VZIG if exposed and not immune**, no live vaccines in pregnancy.", "Listeria: deli meats, ampicillin. Rubella: cataracts, deafness, PDA, blueberry muffin. CMV: **periventricular calcifications**, hearing loss."], "p": 123}, {"t": 5984, "title": "Vulvar disease", "notes": ["Older woman, itchy **ivory white plaques**, perineum: lichen sclerosus. **Biopsy**, high-potency steroid.", "Any suspicious vulvar lesion in an older woman: **biopsy** (squamous cell carcinoma)."], "p": 125}, {"t": 6080, "title": "Amenorrhea: always test for pregnancy", "notes": ["Reproductive-age female with amenorrhea: **beta hCG first**, whatever the story."], "p": 127}, {"t": 6176, "title": "Primary amenorrhea", "notes": ["Breasts + uterus, normal hormones: **imperforate hymen** or transverse septum.", "Breasts + no uterus: **androgen insensitivity (46,XY, high testosterone)** vs **Mullerian agenesis (46,XX)**.", "Short, webbed neck, coarctation, no breasts: **Turner** (high FSH). Low FSH + visual field loss: **craniopharyngioma**. Athlete or anorexia: low GnRH."], "p": 129}, {"t": 6417, "title": "Secondary amenorrhea", "notes": ["Pregnancy, **antipsychotics** (dopamine blockade), hypothyroidism, **prolactinoma** (cabergoline), PCOS, Asherman."], "p": 134}, {"t": 6658, "title": "Primary dysmenorrhea", "notes": ["Adolescent, cramps with menses, normal exam: **NSAIDs**, then combined OCPs."], "p": 139}, {"t": 6754, "title": "Endometriosis and adenomyosis", "notes": ["Endometriosis: dysmenorrhea, **dyspareunia, dyschezia**, infertility, uterosacral nodules. **Laparoscopy** to diagnose. NSAIDs, OCPs, progestin.", "Adenomyosis: older multiparous, **heavy painful periods, symmetric boggy uterus**. Hysterectomy is definitive."], "p": 141}, {"t": 6947, "title": "Postpartum mood disorders", "notes": ["Blues (day 2 to 3): reassure. Depression (weeks): **SSRI**. Psychosis: antipsychotic, admit."], "p": 145}, {"t": 7043, "title": "Postpartum fever by day", "notes": ["Hours: **atelectasis**. Day 1 to 2 with catheter: **UTI**. Day 2 to 3 after cesarean or long ROM: **endometritis**.", "Fever spikes not responding to antibiotics: **septic pelvic thrombophlebitis**, heparin."], "p": 147}, {"t": 7140, "title": "Contraception key points", "notes": ["Only condoms protect against STIs. Combined OCPs **inhibit ovulation**. Progestin-only: thick cervical mucus.", "Estrogen contraindications: **migraine with aura**, smoker over 35, clot history, breast cancer, liver disease, first weeks postpartum.", "Copper IUD: best emergency contraception."], "p": 149}, {"t": 7236, "title": "Prolapse and incontinence", "notes": ["Cystocele: anterior bulge, incomplete emptying. Rectocele: posterior, **splinting**.", "Stress: **positive Q-tip**, pelvic floor, then sling. Urge: bladder training, antimuscarinic. Overflow: high post-void residual, catheterize."], "p": 151}, {"t": 7477, "title": "Vaginitis, endometrial and cervical cancer", "notes": ["Endometrial cancer: **unopposed estrogen** (obesity, PCOS, tamoxifen, nulliparity). Postmenopausal bleeding: **endometrial biopsy** or ultrasound.", "Cervical: squamous most common. **HPV 16 and 18**, smoking, HIV. Postcoital bleeding.", "AGC: colposcopy + endometrial sampling. Hysterectomy for benign reasons: **stop screening**."], "p": 156}, {"t": 7814, "title": "Reproductive hormones and factoids", "notes": ["Prolactin makes milk, **oxytocin lets it down**. hPL: insulin resistance (GDM). hCG maintains the corpus luteum.", "Progesterone: secretory endometrium, thick mucus. Sertoli: **AMH, inhibin**.", "Infertility: 12 months (6 if over 35). **Semen analysis first**."], "p": 163}], "pdf": "Divine%20Intervention%20Ep22.pdf"}];
